const LanguageContext = createContext(null);

function translateDocument(language, originalText) {
  const dictionary = translations[language] || {};
  const translate = (value) => {
    const normalized = value.trim().replace(/\s+/g, " ");
    if (dictionary[normalized]) return dictionary[normalized];

    if (normalized.startsWith("Enroll in ")) {
      const courseName = normalized.slice("Enroll in ".length);
      const translatedCourse = dictionary[courseName] || courseName;
      return `${dictionary["Enroll in"] || "में नामांकन करें"} ${translatedCourse}`;
    }

    const courseNumber = normalized.match(/^COURSE (\d+)$/);
    if (courseNumber) return `${dictionary.Courses || "पाठ्यक्रम"} ${courseNumber[1]}`;

    // Resource action labels include a document name (for example, "View
    // Revert Guide 1"), so they cannot be stored as one fixed dictionary key.
    // Translate both parts to keep these accessible labels localized too.
    for (const action of ["View", "Download"]) {
      const prefix = `${action} `;
      if (normalized.startsWith(prefix)) {
        const documentName = normalized.slice(prefix.length);
        const translatedAction = dictionary[action] || action;
        const translatedDocument = dictionary[documentName]
          || documentName.replace(/^(.*?)(\s+\d+)$/, (_, name, number) => `${dictionary[name] || name}${number}`);
        return `${translatedAction} ${translatedDocument}`;
      }
    }

    return value;
  };
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    if (!node.parentElement.closest("script, style")) {
      const original = originalText.current.get(node) || node.textContent;
      originalText.current.set(node, original);
      const leading = original.match(/^\s*/)[0];
      const trailing = original.match(/\s*$/)[0];
      const translated = `${leading}${translate(original)}${trailing}`;
      if (node.textContent !== translated) node.textContent = translated;
    }
  }
  ["placeholder", "alt", "aria-label", "title"].forEach((attribute) => {
    document.querySelectorAll(`[${attribute}]`).forEach((element) => {
      const dataKey = `original${attribute.replace(/-([a-z])/g, (_, letter) => letter.toUpperCase()).replace(/^./, (letter) => letter.toUpperCase())}`;
      const original = element.dataset[dataKey] || element.getAttribute(attribute);
      if (original) {
        element.dataset[dataKey] = original;
        const translated = translate(original);
        if (element.getAttribute(attribute) !== translated) {
          element.setAttribute(attribute, translated);
        }
      }
    });
  });
}

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => localStorage.getItem("mauiza-language") || "en");
  const selected = languages.find((item) => item.code === language) || languages[0];
  const originalText = useRef(new Map());

  useEffect(() => {
    localStorage.setItem("mauiza-language", language);
    document.documentElement.lang = language;
    document.documentElement.dir = selected.direction;
    document.body.classList.toggle("rtl-language", selected.direction === "rtl");
    translateDocument(language, originalText);

    // React creates new DOM nodes when the route changes and when conditional
    // UI (such as form confirmation messages) appears. Translating only when
    // the select changes leaves those nodes in English, so keep the currently
    // selected language applied to all subsequently rendered content too.
    const observer = new MutationObserver((mutations) => {
      const hasRelevantChange = mutations.some(
        (mutation) =>
          mutation.type === "childList" ||
          (mutation.type === "attributes" && ["placeholder", "alt", "aria-label", "title"].includes(mutation.attributeName))
      );

      if (hasRelevantChange) translateDocument(language, originalText);
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ["placeholder", "alt", "aria-label", "title"],
    });

    return () => observer.disconnect();
  }, [language, selected.direction]);

  return <LanguageContext.Provider value={{ language, setLanguage, selected }}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  return useContext(LanguageContext);
}
